   "detail": "１處置原因：該有價證券之交易，連續三個營業日達本公司「公布注意交易資訊」標準，且該股票於最近三十個營業日內曾發布處置交易資訊。\n２處置期間：自民國一百十五年八月二十五日起至一百十五年八月三十一日﹝五個營業日，如遇：ａ有價證券最後交易日在處置期間，僅處置至最後交易日，ｂ有價證券停止買賣、全日暫停交易則順延執行，ｃ開休市日變動則調整處置迄日〕。\n３處置措施：\nａ該有價證券係變更交易方法為全額交割者，以人工管制之撮合終端機執行撮合作業（約每二十五分鐘撮合一次）\nｂ變更交易方法有價證券，證券經紀商向投資人預收款券須同時合下列規定：\nｉ臺灣證券交易所股份有限公司變更交易方法有價證券交易作業辦法第三條。\nii臺灣證券交易所股份有限公司公布或通知注意交易資訊暨處置作業要點第六條第三項。",
