   "detail": "先進光電科技股份有限公司股票(代號：3362)因連續5個營業日經本中心公布注意交易資訊，且最近5個營業日曾達本中心作業要點第四條第一項第十三款經本中心公布注意交易資訊，爰自115年8月5日起12個營業日(115年8月5日至115年8月20日，如遇休市、有價證券停止買賣、全日暫停交易則順延執行)對先進光電科技股份有限公司國內第一次有擔保轉換公司債（代號：33621）改以人工管制之撮合終端機執行撮合作業(約每5分鐘撮合一次)，各證券商於投資人每日委託買賣該有價證券數量單筆達10交易單位或多筆累積達30交易單位以上時，應就其當日已委託之買賣，向該投資人收取全部之買進價金或賣出證券。但違約專戶委託買賣該有價證券時，不在此限。惟其處置期間屆115年8月10日本中心作業要點第六條第二至第四項新規定實施日，爰修正其處置至115年8月13日止(如遇休市、有價證券停止買賣、全日暫停交易則順延執行)，並自115年8月10日起調整其人工管制之撮合終端機執行撮合作業(改以約每2分鐘撮合一次)。",
   "ruleNote": "8/10新制：12天→7天",
